"""Addresses as they appear in X-Forwarded-For entries and peers (docs/ratelimit.md, section 7.3)."""

import ipaddress
import re

_PORT = re.compile(r"[0-9]{1,5}")


def parse_address(text: str):
    """The address in `text` (optionally with a port or brackets), or None. IPv4-mapped IPv6 becomes IPv4."""
    if text.startswith("["):
        end = text.find("]")
        if end < 0:
            return None
        rest = text[end + 1:]
        if rest and not (rest.startswith(":") and _PORT.fullmatch(rest[1:]) and int(rest[1:]) <= 65535):
            return None
