        if name in names:
            raise ConfigError(f"{what}: name is not unique")
        names.add(name)
        algorithm = t.get("algorithm", "token-bucket")
        if algorithm not in ("token-bucket", "fixed-window"):
            raise ConfigError(f"{what}: unknown algorithm {algorithm!r}")
        rate = values.positive_int(t, "rate", what)
        if "per" not in t:
            raise ConfigError(f"{what}: per is required")
        per_ms = parse_per(t["per"], what)
        if algorithm == "fixed-window":
            if "burst" in t:
                raise ConfigError(f"{what}: burst is not allowed for a fixed-window limit")
            capacity = rate
        else:
            capacity = values.positive_int(t, "burst", what, required=False, missing=rate)
        key = values.string_list(t, "key", what)
        for p in key:
            if p not in PARTS and not (p.startswith("header:") and p[7:]):
                raise ConfigError(f"{what}: unknown key part {p!r}")
