"""Stage 3: rate limiting (docs/ratelimit.md). 429 when a limit is exceeded."""

from fractions import Fraction

from frontdoor.http.addr import client_address, in_any, key_text

NAME = "ratelimit"


class State:
    def __init__(self, config):
        self.limits = config.section("limit", [])
        clients = config.section("clients")
        self.trusted = clients.trusted_proxies if clients else ()
        self.now = None
        self.buckets = [{} for _ in self.limits]
        self.refused = {lim.name: 0 for lim in self.limits}


def setup(config):
    return State(config)


def _ceil_div(frac: Fraction, d: int) -> int:
    return -((-frac) // d)


def _key_values(lim, ctx, client):
    vals = []
    for p in lim.key:
        if p == "tenant":
            v = ctx.tenant
        elif p == "client":
            v = key_text(client) if client is not None else ctx.request.peer
        elif p == "route":
            v = ctx.route.name
        elif p == "method":
            v = ctx.request.method.upper()
        else:
            v = ctx.request.headers.get(p[7:])
            v = v.strip(" \t") if v is not None else None
            v = v or None
        if v is None:
            return None
        vals.append(v)
    return tuple(vals)


def handle(ctx, state):
    if not state.limits:
        return None
    ts = ctx.request.ts_ms
    state.now = ts if state.now is None or ts > state.now else state.now
    now = state.now
    req = ctx.request
    client = client_address(req, state.trusted)
    covering = []
    for i, lim in enumerate(state.limits):
        if lim.routes is not None and ctx.route.name not in lim.routes:
            continue
        if lim.methods is not None and req.method.upper() not in lim.methods:
            continue
        if client is not None and in_any(client, lim.exempt):
            continue
        key = _key_values(lim, ctx, client)
        if key is None:
            continue
        covering.append((i, lim, key))
    if not covering:
        return None

    # bring each covering limit's state up to `now`; entries are (limit, slot dict, key, cost)
    rows = []
    for i, lim, key in covering:
        cost = lim.cost.get(req.method.upper(), 1)
        slots = state.buckets[i]
        if lim.algorithm == "token-bucket":
            level, last = slots.get(key, (Fraction(lim.capacity), now))
            level = min(Fraction(lim.capacity), level + Fraction((now - last) * lim.rate, lim.per_ms))
            slots[key] = (level, now)
        else:
            start = now - now % lim.per_ms
            ws, used = slots.get(key, (start, 0))
            if ws != start:
                ws, used = start, 0
            slots[key] = (ws, used)
        rows.append((i, lim, key, cost))

    def used_of(lim, key):
        return state.buckets[rows_index[lim.name]][key]

    rows_index = {lim.name: i for i, lim, _, _ in rows}

    def allows(lim, key, cost):
        if cost > lim.capacity:
            return False
        slot = state.buckets[rows_index[lim.name]][key]
        if lim.algorithm == "token-bucket":
            return slot[0] >= cost
        return slot[1] + cost <= lim.rate

    verdicts = [allows(lim, key, cost) for _, lim, key, cost in rows]
    allowed = all(verdicts)
    if allowed:
        for _, lim, key, cost in rows:
            slots = state.buckets[rows_index[lim.name]]
            if lim.algorithm == "token-bucket":
                level, last = slots[key]
                slots[key] = (level - cost, last)
            else:
                ws, used = slots[key]
                slots[key] = (ws, used + cost)

    def values_of(lim, key, cost):
        slot = state.buckets[rows_index[lim.name]][key]
        if lim.algorithm == "token-bucket":
            level = slot[0]
            remaining = int(level // 1)
            reset = _ceil_div((lim.capacity - level) * lim.per_ms / Fraction(lim.rate), 1000)
            wait = None if cost > lim.capacity else max(Fraction(0), (cost - level) * lim.per_ms / Fraction(lim.rate))
        else:
            remaining = lim.rate - slot[1]
            to_end = slot[0] + lim.per_ms - now
            reset = _ceil_div(Fraction(to_end), 1000)
            wait = None if cost > lim.capacity else Fraction(to_end)
        return remaining, reset, wait

    if allowed:
        best = None
        for _, lim, key, cost in rows:
            v = values_of(lim, key, cost)
            if best is None or v[0] < best[1][0]:
                best = (lim, v)
        lim, (remaining, reset, _) = best
        ctx.headers["RateLimit-Limit"] = str(lim.capacity)
        ctx.headers["RateLimit-Remaining"] = str(remaining)
        ctx.headers["RateLimit-Reset"] = str(reset)
        return None

    best = None  # (limit, values); wait None = infinite
    for ok, (_, lim, key, cost) in zip(verdicts, rows):
        if ok:
            continue
        state.refused[lim.name] += 1
        v = values_of(lim, key, cost)
        if best is None or (best[1][2] is not None and (v[2] is None or v[2] > best[1][2])):
            best = (lim, v)
    lim, (remaining, reset, wait) = best
    ctx.headers["RateLimit-Limit"] = str(lim.capacity)
    ctx.headers["RateLimit-Remaining"] = str(remaining)
    ctx.headers["RateLimit-Reset"] = str(reset)
    if wait is not None:
        ctx.headers["Retry-After"] = str(max(1, _ceil_div(wait, 1000)))
    return 429


def summary(state):
    if not state.limits:
        return {}
    return {"limited": dict(state.refused)}
